        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    // === Theme ===
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      var icon = document.getElementById('themeIcon');
      var label = document.getElementById('themeLabel');
      if (icon) icon.textContent = t === 'dark' ? '🌙' : '☀️';
      if (label) label.textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    // === Counter ===
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count);
        var prefix = el.dataset.prefix || '';
        var suffix = el.dataset.suffix || '';
        var isDecimal = String(target).indexOf('.') !== -1;
        var start = performance.now();
        var duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1);
          var eased = 1 - Math.pow(1 - p, 3);
          var val = target * eased;
          if (isDecimal) {
            el.textContent = prefix + val.toFixed(1) + suffix;
          } else {
            el.textContent = prefix + Math.round(val) + suffix;
          }
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }
    // Trigger counters immediately for poster capture
    setTimeout(animateCounters, 200);

    // === Chart ===
    var chartsBuilt = false;
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) { this.charts.get(canvasId).destroy(); this.charts.delete(canvasId); }
          var ctx = document.getElementById(canvasId);
          if (!ctx) { console.error('Canvas not found: ' + canvasId); return null; }
          if (ctx.chart) { ctx.chart.destroy(); delete ctx.chart; }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) ctx.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) { console.error('Chart init failed: ' + canvasId, error); return null; }
      },
      updateTheme: function() {
        if (typeof Chart === 'undefined') return;
        this.charts.forEach(function(chart) { try { chart.update(); } catch (e) {} });
      },
      destroyAll: function() {
        this.charts.forEach(function(chart) { try { chart.destroy(); } catch (e) {} });
        this.charts.clear();
      }
    };

    function getChartColors() {
      var s = getComputedStyle(document.documentElement);
      return {
        text: s.getPropertyValue('--text').trim(),
        textSecondary: s.getPropertyValue('--text-secondary').trim(),
        border: s.getPropertyValue('--border').trim(),
        surface: s.getPropertyValue('--surface').trim(),
        accent: s.getPropertyValue('--accent').trim(),
        warning: s.getPropertyValue('--warning').trim(),
        positive: s.getPropertyValue('--positive').trim(),
        negative: s.getPropertyValue('--negative').trim(),
        prePandemic: s.getPropertyValue('--pre-pandemic').trim(),
        bg: s.getPropertyValue('--bg').trim(),
      };
    }

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;
      var colors = getChartColors();
      var isDark = document.documentElement.classList.contains('theme-dark');

      // Growth trajectory chart
      var ctx = resetCanvas('growthChart');
      if (!ctx) return;

      var gridColor = isDark ? 'rgba(255,255,255,0.06)' : 'rgba(0,0,0,0.06)';

      ChartManager.safeInit('growthChart', {
        type: 'line',
        data: {
          labels: ['Jul 2024', 'Oct 2024', 'Jan 2025', 'Apr 2025', 'Jul 2025', 'Oct 2025', 'Jan 2026', 'Apr 2026'],
          datasets: [
            {
              label: 'Growth 2025 (projected)',
              data: [3.3, 3.3, 3.3, 2.9, 3.0, 2.9, 3.3, 2.9],
              borderColor: colors.accent,
              backgroundColor: isDark ? 'rgba(74,144,217,0.1)' : 'rgba(26,95,160,0.08)',
              borderWidth: 3,
              pointRadius: 5,
              pointHoverRadius: 8,
              pointBackgroundColor: colors.accent,
              pointBorderColor: colors.surface,
              pointBorderWidth: 2,
              fill: true,
              tension: 0.3
            },
            {
              label: 'Growth 2026 (projected)',
              data: [null, null, 3.3, 2.9, 3.1, 2.9, 3.2, 2.9],
              borderColor: colors.warning,
              backgroundColor: isDark ? 'rgba(212,118,10,0.08)' : 'rgba(192,102,8,0.06)',
              borderWidth: 3,
              borderDash: [6, 3],
              pointRadius: 5,
              pointHoverRadius: 8,
              pointBackgroundColor: colors.warning,
              pointBorderColor: colors.surface,
              pointBorderWidth: 2,
              fill: true,
              tension: 0.3
            },
            {
              label: 'Pre-pandemic average (~3.8%)',
              data: [3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8, 3.8],
              borderColor: colors.prePandemic,
              borderWidth: 2,
              borderDash: [8, 4],
              pointRadius: 0,
              pointHoverRadius: 0,
              fill: false,
              tension: 0
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          animation: false,
          layout: { padding: { top: 20, right: 20, bottom: 10, left: 10 } },
          plugins: {
            tooltip: {
              enabled: true,
              mode: 'index',
              intersect: false,
              padding: 12,
              cornerRadius: 8,
              titleFont: { size: 14, family: 'Inter' },
              bodyFont: { size: 13, family: 'Inter' },
              callbacks: {
                label: function(ctx) {
                  if (ctx.raw === null) return null;
                  return ctx.dataset.label + ': ' + ctx.raw.toFixed(1) + '%';
                }
              }
            },
            legend: {
              position: 'bottom',
              labels: {
                color: colors.textSecondary,
                font: { size: 13, family: 'Inter' },
                padding: 20,
                usePointStyle: true,
                pointStyleWidth: 16
              }
            }
          },
          scales: {
            x: {
              ticks: { color: colors.textSecondary, font: { size: 12, family: 'Inter' }, maxRotation: 0 },
              grid: { color: gridColor, drawBorder: false },
              title: { display: true, text: 'WEO Edition', color: colors.textSecondary, font: { size: 13, family: 'Inter', weight: '500' } }
            },
            y: {
              min: 2.5,
              max: 4.2,
              ticks: {
                color: colors.textSecondary,
                font: { size: 12, family: 'Inter' },
                callback: function(value) { return value.toFixed(1) + '%'; }
              },
              grid: { color: gridColor, drawBorder: false },
              title: { display: true, text: 'Global Growth (% annual)', color: colors.textSecondary, font: { size: 13, family: 'Inter', weight: '500' } }
            }
          }
        }
      });

      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      ChartManager.destroyAll();
      setTimeout(buildCharts, 100);
    }

    document.addEventListener('DOMContentLoaded', function() {
      buildCharts();
    });

    // Also build on load for safety
    window.addEventListener('load', function() {
      if (!chartsBuilt) buildCharts();
    });

    // === Download PNG ===
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
