const puppeteer = require('puppeteer');
const path = require('path');

(async () => {
  const browser = await puppeteer.launch({
    headless: true,
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--disable-dev-shm-usage']
  });

  const page = await browser.newPage();

  // Set viewport to A0-ish dimensions for high quality
  await page.setViewport({ width: 2400, height: 3394, deviceScaleFactor: 2 });

  const filePath = path.resolve('/app/output/imf_weo_poster.html');
  await page.goto('file://' + filePath, { waitUntil: 'networkidle0', timeout: 30000 });

  // Wait for charts and fonts to load
  await page.evaluate(() => new Promise(resolve => setTimeout(resolve, 3000)));

  // Hide the menu before capture
  await page.evaluate(() => {
    const menu = document.querySelector('.viz-menu');
    if (menu) menu.style.display = 'none';
  });

  // Capture the full body as PNG
  const body = await page.$('body');
  await body.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png'
  });

  console.log('Poster saved to /app/output/final_poster.png');
  await browser.close();
})();

